parameters.jsCode:
// Extraire les paramètres de la requête
const input = $input.first().json;
const query = input.query || {};

const traite = query.traite || null;
const targetLanguage = query.target_language || 'fr';
const discord = query.discord_webhook || null;

return [{
  json: {
    traite: traite,
    targetLanguage: targetLanguage,
    discord: discord ? { webhook_url: discord } : null,
    hasTraite: !!traite
  }
}];

// Formater la réponse pour un traité spécifique
const input = $input.first().json;
const params = $('Parse Parameters').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

if (statusCode >= 400 || data.error) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.error?.message || data.message || 'Erreur API Torah',
        status: 'API_ERROR'
      }
    }
  }];
}

// Calculer les statistiques
const pages = data.pages || [];
const totalPages = pages.length;
const translatedPages = pages.filter(p => p.translated === true).length;
const pendingPages = pages.filter(p => p.translated === false);
const percentage = totalPages > 0 ? Math.round((translatedPages / totalPages) * 100) : 0;

// Construire la réponse
const response = {
  success: true,
  type: 'traite_detail',
  traite: data.traite || params.traite,
  target_language: params.targetLanguage,
  statistics: {
    total_pages: totalPages,
    translated: translatedPages,
    pending: totalPages - translatedPages,
    percentage: percentage
  },
  pages: pages.map(p => ({
    page: p.page,
    translated: p.translated,
    source_text_id: p.source_text_id || null,
    translation_id: p.translation_id || null,
    quality_score: p.quality_score || null,
    status: p.status || null
  })),
  pending_pages: pendingPages.map(p => p.page),
  discord: params.discord
};

return [{ json: response }];

// Formater la réponse globale (liste des traités disponibles)
const input = $input.first().json;
const params = $('Parse Parameters').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

if (statusCode >= 400 || data.error) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.error?.message || data.message || 'Erreur API Torah',
        status: 'API_ERROR'
      }
    }
  }];
}

// Liste des traités disponibles
const traites = data.traites || [];
const total = data.total || traites.length;

// Construire la réponse
const response = {
  success: true,
  type: 'traites_list',
  total: total,
  traites: traites,
  discord: params.discord
};

return [{ json: response }];

