={
  "embeds": [{
    "title": "{{ $json.type === 'traite_detail' ? '📖 Traité ' + $json.traite : '📚 Traités Disponibles' }}",
    "color": 5763719,
    "fields": [
      {{ $json.type === 'traites_list' ? '{"name": "Total", "value": "' + $json.total + ' traités", "inline": true}' : '' }}
      {{ $json.type === 'traites_list' ? ',{"name": "Liste", "value": "' + $json.traites.join(', ') + '", "inline": false}' : '' }}
      {{ $json.type === 'traite_detail' ? '{"name": "Progression", "value": "' + $json.statistics.translated + '/' + $json.statistics.total_pages + ' (' + $json.statistics.percentage + '%)", "inline": true}' : '' }}
      {{ $json.type === 'traite_detail' ? ',{"name": "En attente", "value": "' + $json.statistics.pending + ' pages", "inline": true}' : '' }}
      {{ $json.type === 'traite_detail' && $json.pending_pages.length > 0 ? ',{"name": "Pages à traduire", "value": "' + $json.pending_pages.slice(0,10).join(', ') + ($json.pending_pages.length > 10 ? '...' : '') + '", "inline": false}' : '' }}
    ],
    "footer": { "text": "Torah API" },
    "timestamp": "{{ new Date().toISOString() }}"
  }]
}
